python3 -c "
import pathlib,csv,collections
for p in sorted(pathlib.Path('fixtures/nightly').glob('*.csv')):
    c=collections.Counter()
    with open(p,newline='',encoding='utf-8') as fh:
        for row in csv.DictReader(fh):
            for ch in row.get('unit_price',''):
                if not ch.isdigit() and ch!='.': c[repr(ch)]+=1
    print(p.name, dict(c))
"
